import { Service } from '@angular/core';
import {Concept, ConceptId} from 'concepts-common/interfaces/concept';
import {Observable, of} from 'rxjs';

// TODO: merge this with language service and the similar functionality from graph and timeline

@Service()
export class TitleService {
  private readonly cache: {[type: string] : {[id: string]: Concept}} = {};
  get$(conceptId: ConceptId): Observable<string> {
    const cached = this.cache[conceptId.type]?.[conceptId.id]?.title;
    if (cached) return of(cached);
    return of('HAVE TO FETCH');
  }

  get(conceptId: ConceptId): string | undefined {
    const cached = this.cache[conceptId.type]?.[conceptId.id]?.title;
    if (cached) return cached;
    return undefined;
  }

  set(concept: Concept) {
    if (!this.cache[concept.id.type]) this.cache[concept.id.type] = {};
    this.cache[concept.id.type][concept.id.id] = concept;
  }
}
