import {Component, computed, ElementRef, HostBinding, inject, input, model, signal} from '@angular/core';
import {FormValueControl} from '@angular/forms/signals';
import {ConceptId} from 'concepts-common/interfaces/concept';
import {AsyncPipe, JsonPipe} from '@angular/common';
import {NgbHighlight, NgbTypeahead, NgbTypeaheadSelectItemEvent} from '@ng-bootstrap/ng-bootstrap';
import {FormsModule, ReactiveFormsModule} from '@angular/forms';
import {
  debounceTime,
  distinctUntilChanged, lastValueFrom,
  map,
  Observable,
  OperatorFunction,
  switchMap,
  tap
} from 'rxjs';
import {Backend} from '../../services/backend';
import {ConceptSelector} from 'concepts-common/interfaces/search';
import {TitleService} from '../../services/title';
import {TitlePipe} from '../../pipes/title-pipe';

@Component({
  selector: 'select-concept',
  templateUrl: './select-concept.html',
  imports: [
    JsonPipe,
    NgbHighlight,
    NgbTypeahead,
    ReactiveFormsModule,
    FormsModule,
    TitlePipe,
    AsyncPipe
  ],
  styleUrl: './select-concept.css'
})
export class SelectConceptComponent implements FormValueControl<ConceptId> {
  private bs = inject(Backend);
  private ts = inject(TitleService);
  value = model<ConceptId>({id: '', type: ''});
  searchBase = input<ConceptSelector>({});
  invalid = input<boolean>(false);
  valid = input<boolean>(false);
  title = input<string>('');
  protected searching = signal(false);
  protected selectedTitle = signal('Ziel wählen');

  readonly bootstrapClass = computed(() => {
    const invalid = this.invalid();
    const valid = this.valid();
    if (invalid) return 'is-invalid';
    if (valid) return 'is-valid';
    return 'no-bs';
  });

  protected searchConcept: OperatorFunction<string, readonly ConceptId[]> = (text$: Observable<string>) =>
    text$.pipe(
      debounceTime(300),
      distinctUntilChanged(),
      tap(() => this.searching.set(true)),
      switchMap(term=>
        this.bs.search({...this.searchBase(), q: term, shards: ['title']})
          .pipe(
            map(sr => sr.results
              .map(c => {
                this.ts.set(c);
                console.log(c.id)
                return c.id;
              })
            )
          ),
      ),
      tap(() => {
        this.searching.set(false)
      }),
    );

  static fullId = (cId: ConceptId): string => `#${cId.type}/${cId.id}`;

  protected inputFormatter = (cId: ConceptId | undefined): string =>
    (!cId || !cId.id || !cId.type) ? '' : SelectConceptComponent.fullId(cId);

  protected async select(event: NgbTypeaheadSelectItemEvent<ConceptId>) {
    this.selectedTitle.set(await lastValueFrom(this.ts.get$(event.item)));
  }
}
